/**
 * A camera stream arriving at UXDuck.
 */
export type VideoSource = {
    /**
     * Why it is on `activeUrl` and since when.
     */
    activeChoice?: AddressChoice | null;
    /**
     * The address currently being tried or played, redacted on the wire.
     */
    activeUrl?: string | null;
    /**
     * Added by hand: it stays until removed.
     */
    addedByHand?: boolean;
    assignedByHand?: boolean;
    /**
     * Its sound, once its stream is known, and whether UXDuck records it
     * (S147).
     */
    audio?: VideoAudio | null;
    /**
     * Local device capture and its encoding provenance; absent for network cameras.
     */
    capture?: CaptureInput | null;
    changedAtUs: number;
    /**
     * The WebCodecs codec string, such as `hvc1.1.2.L120` or `avc1.64001f`.
     */
    codec?: string | null;
    container: VideoContainer;
    counters: VideoCounters;
    /**
     * Other addresses of this same camera, in preference order. Only one plays.
     */
    fallbackUrls?: Array<string>;
    file?: VideoFileInput | null;
    firstSeenUs: number;
    frameRate?: number | null;
    height?: number | null;
    id: string;
    /**
     * Direct local routes and an optional smaller stream from the same camera.
     */
    internet?: CameraInternet | null;
    /**
     * It carries KLV metadata.
     */
    klv?: boolean;
    /**
     * Its address, such as `udp://127.0.0.1:5600` or an RTSP address
     * without its password, until someone renames it.
     */
    name: string;
    /**
     * Someone named it (`video/rename`).
     */
    namedByHand?: boolean;
    /**
     * The UDP port it arrives on.
     */
    port: number;
    /**
     * "Record with the others" is off (S153): neither the recording
     * setting nor `video/recordAll` starts it, only `video/record`
     * (`video/recordWithOthers`).
     */
    recordAlone?: boolean;
    /**
     * Recording intent, including while reconnecting. Record can stop it then too.
     */
    recordingRequested?: boolean;
    /**
     * The encoder re-encoding it for live view now (`h264_videotoolbox`,
     * `libx264`, ...), for a camera that sends no IDR; absent otherwise.
     */
    reencoding?: string | null;
    /**
     * The sender's address and port.
     */
    sender: string;
    /**
     * The companion computer serving an RTSP camera, by its id in the
     * vehicle's `companions`, chosen by hand (S358, `video/servedBy`): its
     * TIMESYNC clock dates the pictures. Absent: the computer whose host is
     * the camera address's host.
     */
    servedBy?: string | null;
    state: VideoState;
    stateDetail?: string | null;
    /**
     * Every video track an RTSP camera offers, the one playing marked;
     * empty until it answers, and for UDP. `video/track` chooses another.
     */
    tracks?: Array<VideoTrack>;
    /**
     * Where UXDuck fetches it, such as an RTSP address, without its password.
     */
    url?: string | null;
    /**
     * Its vehicle's own camera takes a photo and records along with
     * UXDuck (S145): on for a stream the vehicle's camera announced, else
     * off, until set by hand (`video/vehicleCamera`).
     */
    vehicleCamera?: boolean;
    /**
     * The vehicle it belongs to: by the sender's address, or chosen.
     */
    vehicleId?: string | null;
    version: number;
    width?: number | null;
};

export type VideoState = 'receiving' | 'stopped' | 'unsupported';

/**
 * One video track of an RTSP camera, as its SDP describes it.
 */
export type VideoTrack = {
    /**
     * "H.264", "H.265" or "MPEG-TS".
     */
    codec: string;
    frameRate?: number | null;
    height?: number | null;
    /**
     * From 1, in the camera's order: what `#track=N` on the address names.
     */
    number: number;
    /**
     * The one this source plays.
     */
    playing?: boolean;
    width?: number | null;
};

export type VideoTrackParams = {
    /**
     * An RTSP source added by hand.
     */
    sourceId: string;
    /**
     * The track to play, from 1 as in `tracks`; 1 is the camera's first,
     * the default. Kept with the source as `#track=N` on its address.
     */
    track: number;
};

export type VideoUnwatchParams = {
    token: string;
};

export type VideoVehicleCameraParams = {
    /**
     * Whether the vehicle's own camera takes photos and records along.
     */
    on: boolean;
    sourceId: string;
};

export type VideoWatchParams = {
    sourceId: string;
};

export type VideoWatchResult = {
    /**
     * Open a WebSocket on this path of the daemon's origin within 30 s;
     * its binary messages are the source's access units, from a keyframe.
     */
    path: string;
    /**
     * Names this watch for `video/unwatch`; closing the socket also ends it.
     */
    token: string;
};

/**
 * How often each of the daemon's tasks has woken since it started (S24),
 * so an idle daemon that is not idle can be traced to its cause.
 */
export type Wakeups = {
    /**
     * Microseconds since the Unix epoch when counting began.
     */
    sinceUs: number;
    /**
     * Most first.
     */
    tasks: Array<TaskWakeups>;
};

/**
 * `GET /v1/watch/{token}`: what a guest's page needs before it connects.
 */
export type WatchInfo = {
    expiresAtMs: number;
    flownBy: string;
    vehicleId?: string | null;
    vehicleName?: string | null;
};

/**
 * A watch link (S95, ADR-0023): anyone holding its address watches one
 * computer, one vehicle on it or all of them, until it ends. The token is
 * shown once, when it is made; the API keeps only its hash.
 */
export type WatchLink = {
    createdAtMs: number;
    deviceId: string;
    expiresAtMs: number;
    /**
     * Who flies, as the owner typed it: shown on the watch page, never an email.
     */
    flownBy: string;
    /**
     * `wl` and 16 hex digits.
     */
    id: string;
    /**
     * The vehicle it shows; none for every vehicle on the computer.
     */
    vehicleId?: string | null;
    /**
     * The vehicle's name when the link was made, for the owner's list.
     */
    vehicleName?: string | null;
};

/**
 * `POST /v1/watch-links`: the owner making a link at their computer.
 */
export type WatchLinkCreate = {
    deviceId: string;
    /**
     * The computer's name, so a computer that has not connected yet is
     * known to the account: it connects only once it has a link.
     */
    deviceName?: string | null;
    flownBy: string;
    /**
     * How long it lasts: 24 by default, 168 (a week) at most.
     */
    hours?: number | null;
    vehicleId?: string | null;
    vehicleName?: string | null;
};

/**
 * `watchLink/create`: a watch link for this computer (S95), or for one
 * vehicle on it. Needs the account signed in and "Live sharing from this
 * computer" on.
 */
export type WatchLinkCreateParams = {
    /**
     * Who flies, shown on the page: the operator's name, never an email.
     */
    flownBy: string;
    /**
     * How long it lasts: 24 by default, 168 at most.
     */
    hours?: number | null;
    /**
     * The vehicle it shows; every vehicle on this computer when absent.
     */
    vehicleId?: string | null;
};

/**
 * The answer to `watchLink/create`: the link and its address, shown once.
 */
export type WatchLinkCreateResult = {
    link: WatchLink;
    /**
     * The watch page's address, with the token in it.
     */
    url: string;
};

/**
 * The answer to `POST /v1/watch-links`: the link, and its token, once.
 */
export type WatchLinkCreated = {
    link: WatchLink;
    token: string;
};

/**
 * `GET /v1/watch-links`: the owner's links that have not ended.
 */
export type WatchLinkList = {
    links: Array<WatchLink>;
};

/**
 * The answer to `watchLink/list`.
 */
export type WatchLinkListResult = {
    /**
     * How this computer's connection for live sharing is going: links
     * show nothing while it is not connected.
     */
    edge: EdgeStatus;
    links: Array<WatchLinkStatus>;
};

/**
 * `watchLink/revoke`.
 */
export type WatchLinkRevokeParams = {
    linkId: string;
};

/**
 * One of this computer's watch links, with how many watch through it now.
 */
export type WatchLinkStatus = {
    link: WatchLink;
    watching: number;
};

/**
 * `POST /v1/watch/{token}/video`: a guest asking to play one camera.
 */
export type WatchVideoRequest = {
    cameraId: string;
    nodeId?: string | null;
};

/**
 * How many guests watch through one watch link now (S95).
 */
export type WatchViewers = {
    count: number;
    linkId: string;
    /**
     * The vehicle the link shows; none for every vehicle on the computer.
     */
    vehicleId?: string | null;
};

/**
 * The answer to `watchLink/viewers`, and `watchLink/viewersChanged`: the
 * vehicles someone watches now, for "N watching" beside each (S95, W6).
 * A vehicle nobody watches is left out.
 */
export type WatchViewersResult = {
    vehicles: Array<VehicleWatching>;
};

export type WatchdogChange = 'install' | 'remove';

export type WatchdogRestart = {
    /**
     * When, by the computer's clock.
     */
    atUs: number;
    /**
     * The camera that had stopped.
     */
    path: string;
};

/**
 * What a panel shows (X5). Every widget may have `help`, plain text shown
 * behind an info icon, and a tone. Items are the focused vehicle's, by key.
 */
export type Widget = {
    heading?: boolean;
    help?: string | null;
    text: string;
    tone?: Tone | null;
    type: 'text';
} | {
    help?: string | null;
    item: string;
    label: string;
    tone?: Tone | null;
    type: 'value';
} | {
    help?: string | null;
    item: string;
    label: string;
    max: number;
    min: number;
    tone?: Tone | null;
    type: 'gauge';
    warnAbove?: number | null;
    warnBelow?: number | null;
} | {
    help?: string | null;
    item: string;
    label: string;
    tone?: Tone | null;
    type: 'chart';
    windowS?: number;
} | {
    columns: Array<string>;
    help?: string | null;
    item: string;
    label: string;
    tone?: Tone | null;
    type: 'table';
} | {
    /**
     * Fractions of a second may show, when the person turns them on:
     * hundredths while it counts, milliseconds while it is still. The
     * value shows as sent, so send a still one exactly, not rounded.
     */
    fractions?: boolean;
    help?: string | null;
    item: string;
    label: string;
    tone?: Tone | null;
    type: 'display';
} | {
    command: string;
    help?: string | null;
    label: string;
    params?: {
        [key: string]: unknown;
    } | null;
    tone?: Tone | null;
    type: 'button';
} | {
    command: string;
    help?: string | null;
    label: string;
    tone?: Tone | null;
    type: 'time-input';
};

/**
 * A saved network, without its credentials.
 */
export type WifiNetwork = {
    active: boolean;
    id: string;
    /**
     * Profiles created by UXDuck can be updated here.
     */
    managed: boolean;
    ssid: string;
};

export type WifiProfileParams = {
    hidden: boolean;
    metered: boolean;
    /**
     * Used once on the companion. Never stored in UXDuck or returned.
     */
    password: string;
    priority: number;
    security: WifiSecurity;
    ssid: string;
};

export type WifiSecurity = 'open' | 'wpa-psk' | 'sae';

export type WriteState = 'writing' | 'written' | 'refused';

/**
 * How a write to the vehicle ended.
 */
export type WriteStatus = 'accepted' | 'rejected' | 'timeout' | 'not-sent';

/**
 * An agent's draft: which agent wrote it, and in which chat.
 */
export type WrittenBy = {
    /**
     * The agent's name, such as "UXDuck agent" or "Claude Code".
     */
    agent: string;
    threadId?: string | null;
};
